/**
 * The crawlseo logo. The mark uses the brand colour, the word follows the
 * text colour. Size it with a height class only, e.g. "h-6 w-auto".
 */
export function Logo({
  variant = "lockup",
  className = "",
  decorative = false,
}: {
  variant?: LogoVariant;
  className?: string;
  /** Inside a link that already says "crawlseo": hide the svg from assistive tech. */
  decorative?: boolean;
}) {
  const logo = LOGOS[variant];
  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      viewBox={logo.viewBox}
      {...(decorative ? { "aria-hidden": true } : { role: "img", "aria-label": "crawlseo" })}
      className={["block w-auto", className].filter(Boolean).join(" ")}
    >
      <path d={logo.mark} fill="var(--brand-500)" />
      {logo.word && <path d={logo.word} fill="currentColor" />}
    </svg>
  );
}
